        public NoteCounts Dispensed { get; private set; }

        public bool Dispense(NoteCounts notes)
        {
            DispenseCalls++;
            if (DispenseCalls == failOnDispenseCall)
            {
                return false;
            }

            Stock -= notes;
            Dispensed += notes;
            return true;
        }

        public bool Load(NoteCounts notes)
        {
            LoadCalls++;
            if (failLoad)
            {
                return false;
            }

            Stock += notes;
            return true;
        }
    }
}
